fn is_a_checkout_of(dir: &Path, common: &Path) -> bool {
    let real = |path: &Path| path.canonicalize().unwrap_or_else(|_| path.to_path_buf());
    let Some(out) = std::process::Command::new("git")
        .arg("-C")
        .arg(dir)
        .args([
            "rev-parse",
            "--path-format=absolute",
            "--show-toplevel",
            "--git-common-dir",
        ])
        .output()
        .ok()
        .filter(|out| out.status.success())
    else {
        return false;
    };
    let said = String::from_utf8_lossy(&out.stdout);
    let mut lines = said.lines().map(|line| real(Path::new(line)));
    matches!(
        (lines.next(), lines.next(), lines.next()),
        (Some(toplevel), Some(at_dir), None) if toplevel == real(dir) && at_dir == real(common)
    )
}

fn provisioning_checkout(repo_root: &Path, common: &Path) -> Option<PathBuf> {
    let id = repo_root.file_name()?.to_str()?;
    let minted = engine::milestone::worktree_path(id);
    if !repo_root.ends_with(&minted) {
        return None;
    }
    let mut home = repo_root;
    for _ in minted.components() {
        home = home.parent()?;
    }
    is_a_checkout_of(home, common).then(|| home.to_path_buf())
}
4. Replace the whole body of the existing `pub fn home_is_a_checkout(home: &Path, standing: &Path) -> bool` with the one line (meaning unchanged, one implementation):
    git_common_dir(standing).is_some_and(|common| is_a_checkout_of(home, &common))
5. Extend the doc comment on `jigc_home` to state the rule: (1) `.git` a directory → the walk-up root; (2) `.git` a file and `dirname(git-common-dir)` is the top of a work tree of this repository, asked of git → that directory; (3) else, if the standing checkout sits at `<home>/.jigc/worktrees/<id>` and `<home>` is a checkout of this repository → `<home>`; (4) else the standing checkout. A probe git cannot answer reads as the standing checkout.
